const runIndex = $runIndex;
const productImage = $('When Executed by Another Workflow').item.json.product_image;
const influencerImage = $node['influencer_image_to_base_64'].json.data;

// Determine which prompt to use
let promptText;

if (runIndex % 2 === 0) {
  // Before/After prompt - ENGLISH ONLY LABEL
  const poseVariation = Math.floor(runIndex / 2) % 4;
  const poses = [
    'front view with hands touching hair on AFTER side',
    'slight side angle showing hair length',
    'three-quarter view with hair flowing over shoulder',
    'front view with hands running through hair on AFTER side'
  ];

  promptText = 'Create a professional before/after split-screen comparison image showcasing hair extensions transformation. LEFT SIDE (BEFORE): Use the person from image 2 with their natural hair length and texture. RIGHT SIDE (AFTER): Transform the same person with luxurious, voluminous hair extensions matching the style and color from image 1.\n\nSPECIFIC REQUIREMENTS:\n- Split the canvas exactly 50/50 vertically with a thin white divider line\n- Add BEFORE text in elegant serif font (like Playfair Display) at top left\n- Add AFTER text in same font at top right\n- BEFORE side: Person with shorter/thinner natural hair, neutral expression, straight hair\n- AFTER side: Same person with fuller, longer, voluminous hair, bright happy smile, styled with soft waves, confident pose touching hair\n- Same person, same outfit, same background in both sides\n- Background: Soft, blurred interior setting (salon or home) with warm neutral tones\n- Lighting: Professional, soft, flattering light on face\n- Hair color continuity: AFTER hair should seamlessly blend with natural color but add length/volume from image 1\n- Pose variation: ' + poses[poseVariation] + '\n- Professional beauty/salon advertisement quality\n- Add a small, rectangular branding overlay at bottom center with text "ZEN HAIR EXTENSIONS" in elegant serif font (black text on a light white background, clearly visible and sharp, similar to a discreet product label). Ensure the label is unobtrusive yet prominent. ONLY ENGLISH TEXT - no Urdu translation in this label. This image should NOT include any additional text other than BEFORE/AFTER and the English branding label.\n\nSTYLE: High-end hair salon advertisement, professional beauty photography, Instagram-worthy, clean and polished. Output only the final composite before/after image.';
} else {
  // Lifestyle photo prompt with BILINGUAL taglines (English + Urdu)
  const angleVariation = Math.floor(runIndex / 2) % 5;
  const taglineIndex = Math.floor(runIndex / 2) % 6;

  const taglines = [
{ english: 'Effortless Glamour, Instantly.', urdu: 'آسانی کے ساتھ گلیمر، فوری طور پر۔' },
{ english: 'Your Best Hair, Every Day.', urdu: 'آپ کے بہترین بال، ہر روز۔' },
{ english: 'Length. Volume. Confidence.', urdu: 'لمبائی۔ والیوم۔ اعتماد۔' },
{ english: 'Transform in Seconds.', urdu: 'سیکنڈوں میں تبدیلی لائیں۔' },
{ english: 'Luxurious Hair, Made Easy.', urdu: 'شاندار بال، آسانی سے حاصل کریں۔' },
{ english: 'Glamour Without Limits.', urdu: 'بے حد گلیمر۔' }
  ];

  const angles = [
    'front view facing camera with hair framing the face, confident smile',
    'side profile view showing the full hair length and volume cascading down',
    'back view showcasing the complete length, texture and flow of the hair',
    'three-quarter angle showing both face and hair flowing naturally over shoulder',
    'dynamic pose with hair in gentle motion, hand naturally touching or running through hair'
  ];

  const selectedTagline = taglines[taglineIndex];

  promptText = 'Create a realistic, high-quality lifestyle photograph showcasing luxurious hair extensions. The person should have beautiful, long, flowing hair similar in style, color, and texture to the hair extensions shown in image 1. Use the person' + String.fromCharCode(39) + 's facial features, skin tone, and overall appearance from image 2 as the model reference.\n\nSETTING & COMPOSITION:\n- Location: Elegant outdoor or upscale indoor setting (rooftop terrace, modern balcony, luxury hotel, stylish cafe, or sophisticated urban backdrop)\n- The person should look confident, happy, and naturally glamorous\n- Hair should be clearly visible, well-lit, and the focal point of the image\n- Camera angle: ' + angles[angleVariation] + '\n- Professional photography quality but with authentic, lifestyle feel\n\nLIGHTING & STYLE:\n- Natural, flattering golden hour or soft diffused lighting\n- Hair should appear shiny, healthy, with visible texture and movement\n- Color grading: Warm, elegant tones with professional polish\n- Overall aesthetic: Premium lifestyle advertisement, Instagram-worthy\n\nBILINGUAL TEXT OVERLAY REQUIREMENTS (CRITICAL):\n- Add a bilingual text overlay at the TOP CENTER of the image with TWO LINES\n- FIRST LINE (English): "' + selectedTagline.english + '" in elegant serif font (like Playfair Display)\n- SECOND LINE (Urdu): "' + selectedTagline.urdu + '" directly below the English text. The Urdu text must be rendered in a **clear, elegant, standard Urdu font (like Naskh)**, accurately written **right-to-left**, with **correct character formation and joining of letters**.\n- Style: White or light cream colored text with subtle shadow for readability OR on a subtle semi-transparent overlay\n- Both lines should be center-aligned, prominent, and clearly readable\n- Text should have an ethereal, premium feel matching elegant advertisement aesthetics\n- Maintain proper spacing between the English and Urdu lines\n\nIMPORTANT:\n- Ensure the person' + String.fromCharCode(39) + 's ethnicity, facial features, and skin tone from image 2 are accurately represented\n- Hair color and style should seamlessly match image 1 while looking natural on the person\n- Create a cohesive, professional advertisement image\n- **ABSOLUTELY NO OTHER TEXT, watermarks, or labels** should be present in the image, except for the specified bilingual tagline at the top.\n\nOutput only the final generated lifestyle image with the bilingual (English + Urdu) tagline overlay at the top.';
}

// Build the request body
const requestBody = {
  contents: [
    {
      parts: [
        {
          text: promptText
        },
        {
          inline_data: {
            mime_type: "image/png",
            data: productImage
          }
        },
        {
          inline_data: {
            mime_type: "image/jpeg",
            data: influencerImage
          }
        }
      ]
    }
  ]
};

return {
  json: {
    requestBody: JSON.stringify(requestBody)
  }
};
